using CoopBeam;
public static class IceKingdomBuilder {
 const string Root="Assets/ReinoDeHielo/";const string Art=Root+"0_3_Art/";const string Heroes="Assets/Prototype_CoopBeam/0_2_Prefabs/";
 static Material mat;static Sprite tile,spark;static EnemyBase[] prefabs;static Sprite[] backgrounds;
 public static readonly string[] Titles={"VALLE DE LOS COPOS","PUERTO A LA DERIVA","GRUTAS DE AURORA","BASTION DEL VENTISQUERO","CORONA DEL REY CENCELLON"};
 static readonly string[] Lessons={"Nieve avisa, lazo responde.\nRecojan prismas, burbujas y corazones con el lazo.","Los pinguinos anuncian su deslizamiento.\nSalten juntos; aprovechen su recuperacion.","Las lechuzas fijan el lugar antes de picar.\nUsen alturas distintas y muevan el lazo.","Las pasarelas se rompen; las torretas apuntan.\nCambien de ruta antes de la embestida del oso.","El rey cierra su nucleo mientras ataca.\nBusquen huecos; rodeenlo al abrir su corazon.\nCarguen la ulti: Mora Q / Lima Shift derecho."};
 [MenuItem("Coop Beam/Expansion/Build Ice Kingdom Only")]
 public static void Build(){if(EditorApplication.isPlaying)throw new Exception("Exit Play first");var original=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(original.isDirty)throw new Exception("Unsaved scene: save manually before building");string originalPath=original.path;
  foreach(var path in Enumerable.Range(1,5).Select(n=>CandyCampaign.ScenePath(n,true)))if(File.Exists(path))throw new Exception("Ice scenes already exist. Builder never overwrites existing levels: "+path);
  mat=AssetDatabase.LoadAssetAtPath<Material>("Assets/Prototype_CoopBeam/0_3_Art/SpriteUnlit.mat");spark=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/ReinoDeChicle/0_3_Art/PixelArt/Tiles/PixelSpark.png");if(!spark)spark=AssetDatabase.LoadAssetAtPath<Sprite>("Assets/Prototype_CoopBeam/0_3_Art/mote.png");tile=MakeTile();backgrounds=Backgrounds();
  prefabs=new EnemyBase[7];for(int i=0;i<6;i++)prefabs[i]=MakeEnemy(i);prefabs[6]=MakeBoss();
  for(int n=1;n<=5;n++)BuildScene(n);
  var builds=EditorBuildSettings.scenes.ToList();for(int n=1;n<=5;n++){string path=CandyCampaign.ScenePath(n,true);if(!builds.Any(s=>s.path==path))builds.Add(new EditorBuildSettingsScene(path,true));}EditorBuildSettings.scenes=builds.ToArray();AssetDatabase.SaveAssets();if(!string.IsNullOrEmpty(originalPath))EditorSceneManager.OpenScene(originalPath);Debug.Log("ICE_KINGDOM_BUILT: five new scenes, six enemies, King Cencellon; existing candy scenes untouched.");
 }
 static Texture2D Import(string path,bool readable=true){AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Default;imp.isReadable=readable;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.alphaIsTransparency=true;imp.npotScale=TextureImporterNPOTScale.None;imp.maxTextureSize=4096;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 static Sprite[] Frames(string file,string name,int cols,int rows,int row,int count,float height){var texture=Import(Art+file);string path=Art+name+".asset";var set=ScriptableObject.CreateInstance<PixelAnimationSet>();AssetDatabase.CreateAsset(set,path);set.frames=new Sprite[count];int w=texture.width/cols,h=texture.height/rows;float ppu=1;
  for(int f=0;f<count;f++){int cx=f%cols,cy=rows-1-(row+f/cols);int x=cx*w,y=cy*h;int minX=w,minY=h,maxX=0,maxY=0;for(int yy=0;yy<h;yy++)for(int xx=0;xx<w;xx++)if(texture.GetPixel(x+xx,y+yy).a>.35f){minX=Mathf.Min(minX,xx);maxX=Mathf.Max(maxX,xx);minY=Mathf.Min(minY,yy);maxY=Mathf.Max(maxY,yy);}if(maxY<=minY)throw new Exception("Empty sprite cell "+name+" "+f);if(f==0)ppu=(maxY-minY+1)/height;
   var frame=Sprite.Create(texture,new Rect(x,y,w,h),new Vector2((minX+maxX)*.5f/w,(float)minY/h),ppu,0,SpriteMeshType.FullRect);frame.name=name+"_"+f.ToString("00");AssetDatabase.AddObjectToAsset(frame,set);set.frames[f]=frame;
  }EditorUtility.SetDirty(set);return set.frames;
 }
 static Sprite[] Backgrounds(){var texture=Import(Art+"IceBackgrounds.png",false);var set=ScriptableObject.CreateInstance<PixelAnimationSet>();AssetDatabase.CreateAsset(set,Art+"WinterBackdrops.asset");set.frames=new Sprite[5];int h=texture.height/5;for(int i=0;i<5;i++){var s=Sprite.Create(texture,new Rect(0,(4-i)*h,texture.width,h),Vector2.one*.5f,32,0,SpriteMeshType.FullRect);s.name=Titles[i];AssetDatabase.AddObjectToAsset(s,set);set.frames[i]=s;}EditorUtility.SetDirty(set);return set.frames;}
 static Sprite MakeTile(){var t=new Texture2D(64,16,TextureFormat.RGBA32,false);for(int y=0;y<16;y++)for(int x=0;x<64;x++){Color c=y>12?new Color(.88f,1,1):y>9?new Color(.44f,.82f,.95f):new Color(.12f,.34f,.55f);if(y<10&&(x+y*2)%17<2)c=new Color(.3f,.6f,.8f);if(y==0)c=new Color(.08f,.16f,.3f);t.SetPixel(x,y,c);}t.Apply();string path=Art+"FrostTile.png";File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.textureType=TextureImporterType.Sprite;imp.spritePixelsPerUnit=32;imp.filterMode=FilterMode.Point;imp.mipmapEnabled=false;imp.textureCompression=TextureImporterCompression.Uncompressed;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Sprite>(path);}
 static GameObject Visual(string name,Sprite sprite,Transform parent,Vector2 point,int order){var g=new GameObject(name);if(parent)g.transform.SetParent(parent,false);g.transform.localPosition=point;var r=g.AddComponent<SpriteRenderer>();r.sprite=sprite;r.sharedMaterial=mat;r.sortingOrder=order;return g;}
 static EnemyBase MakeEnemy(int index){string[] names={"SnowmanGrenadier","CrystalPolarBear","PenguinSledder","AuroraOwl","FrostTurret","FrostImp"};float[] heights={1.35f,1.8f,1.15f,1.4f,1.5f,1.1f};var frames=Frames("IceEnemies.png",names[index],8,6,index,8,heights[index]);var g=new GameObject(names[index]);g.layer=10;var body=g.AddComponent<Rigidbody2D>();body.bodyType=index==3||index==4?RigidbodyType2D.Kinematic:RigidbodyType2D.Dynamic;body.gravityScale=3;body.freezeRotation=true;body.useFullKinematicContacts=true;body.collisionDetectionMode=CollisionDetectionMode2D.Continuous;body.interpolation=RigidbodyInterpolation2D.Interpolate;
  var col=g.AddComponent<CapsuleCollider2D>();col.size=new Vector2(index==1?1.25f:.85f,index==1?1.5f:1);var visual=Visual("Pixel art",frames[0],g.transform,Vector2.down*col.size.y*.5f,4);var e=g.AddComponent<EnemyBase>();e.kind=index==3?EnemyKind.Flyer:index==4?EnemyKind.Cannon:index==1?EnemyKind.Armored:index==5?EnemyKind.Jumper:EnemyKind.Walker;e.maxHealth=new[]{48f,110,42,48,65,38}[index];e.speed=1;e.sprite=visual.GetComponent<SpriteRenderer>();e.visual=visual.transform;var ai=g.AddComponent<IceEnemyBrain>();ai.role=(IceEnemyBrain.Role)index;ai.interval=4.5f;var animation=visual.AddComponent<IceSpriteAnimator>();animation.frames=frames;visual.AddComponent<PixelActorVisual>();g.AddComponent<ActorPhysics2D>();var p=PrefabUtility.SaveAsPrefabAsset(g,Root+"0_2_Prefabs/"+names[index]+".prefab");UnityEngine.Object.DestroyImmediate(g);return p.GetComponent<EnemyBase>();
 }
 static EnemyBase MakeBoss(){var frames=Frames("KingCencellon.png","KingCencellon",4,4,0,16,4.2f);var g=new GameObject("Rey Cencellon");g.layer=12;var body=g.AddComponent<Rigidbody2D>();body.bodyType=RigidbodyType2D.Kinematic;body.useFullKinematicContacts=true;var col=g.AddComponent<BoxCollider2D>();col.size=new Vector2(2.6f,3.2f);var visual=Visual("Crystal monarch",frames[0],g.transform,Vector2.down*1.6f,4);var enemy=g.AddComponent<EnemyBase>();enemy.kind=EnemyKind.Boss;enemy.maxHealth=480;enemy.sprite=visual.GetComponent<SpriteRenderer>();enemy.visual=visual.transform;var king=g.AddComponent<IceKingBoss>();var core=new GameObject("Aurora heart - ray target");core.layer=10;core.transform.SetParent(g.transform,false);core.transform.localPosition=Vector3.up*.3f;var c=core.AddComponent<CircleCollider2D>();c.isTrigger=true;c.radius=.6f;king.core=c;var light=Visual("Exposed aurora",spark,g.transform,Vector2.up*.3f,6);light.transform.localScale=Vector3.one*.7f;king.coreArt=light.GetComponent<SpriteRenderer>();var animation=visual.AddComponent<IceSpriteAnimator>();animation.frames=frames;animation.boss=true;var p=PrefabUtility.SaveAsPrefabAsset(g,Root+"0_2_Prefabs/KingCencellon.prefab");UnityEngine.Object.DestroyImmediate(g);return p.GetComponent<EnemyBase>();}
 static GameObject Platform(string name,Vector2 point,Vector2 size,bool semi=true,int mode=-1){var g=new GameObject(name);g.transform.position=point;g.layer=semi?9:8;var col=g.AddComponent<BoxCollider2D>();col.size=size;if(semi){col.usedByEffector=true;var eff=g.AddComponent<PlatformEffector2D>();eff.useOneWay=true;eff.useOneWayGrouping=true;eff.surfaceArc=165;}var v=Visual("Snow capped ice",tile,g.transform,Vector2.zero,0);v.transform.localScale=new Vector3(size.x/tile.bounds.size.x,size.y/tile.bounds.size.y,1);if(mode>=0){var env=g.AddComponent<CandyEnvironment>();env.kind=(CandySurfaceKind)mode;env.art=v.transform;env.strength=mode==0?16:1.4f;if(mode==2){var rb=g.AddComponent<Rigidbody2D>();rb.bodyType=RigidbodyType2D.Kinematic;env.travel=1.6f;env.period=5;}}return g;}
 static void BuildScene(int number){var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var cam=new GameObject("Winter pixel camera",typeof(Camera),typeof(AudioListener)).GetComponent<Camera>();cam.tag="MainCamera";cam.orthographic=true;cam.orthographicSize=7.5f;cam.transform.position=new Vector3(0,1,-10);cam.backgroundColor=new Color(.07f,.09f,.2f);cam.gameObject.AddComponent<ArenaCamera>();cam.gameObject.AddComponent<PixelViewport>();var bg=Visual("Winter backdrop",backgrounds[number-1],null,new Vector2(0,1),-30);bg.transform.localScale=new Vector3(26/backgrounds[number-1].bounds.size.x,15/backgrounds[number-1].bounds.size.y,1);bg.GetComponent<SpriteRenderer>().color=new Color(.65f,.72f,.85f);
  Platform("Frozen foundation",new Vector2(0,-4.7f),new Vector2(23,.8f),false);
  if(number==1){Platform("Snowbank west",new Vector2(-6,-2.1f),new Vector2(5,.45f));Platform("Snowbank east",new Vector2(6,-2.1f),new Vector2(5,.45f));Platform("Crystal bridge",new Vector2(0,.1f),new Vector2(4.5f,.45f));}
  if(number==2){Platform("Drifting floe west",new Vector2(-6,-2.1f),new Vector2(4.5f,.45f),true,2);Platform("Drifting floe east",new Vector2(6,-1.8f),new Vector2(4,.45f),true,2);Platform("Frozen dock",new Vector2(0,.4f),new Vector2(4,.45f));Platform("High dock",new Vector2(-6,2.5f),new Vector2(3.5f,.45f));}
  if(number==3){Platform("Crystal spring west",new Vector2(-6,-2.1f),new Vector2(4,.5f),true,0);Platform("Crystal spring east",new Vector2(6,-2.1f),new Vector2(4,.5f),true,0);Platform("Aurora shelf",new Vector2(0,.4f),new Vector2(5,.45f));Platform("Geode west",new Vector2(-6,2.7f),new Vector2(4,.45f));Platform("Geode east",new Vector2(6,2.7f),new Vector2(4,.45f));}
  if(number==4){Platform("Thin ice west",new Vector2(-6,-2.1f),new Vector2(5,.5f),true,3);Platform("Thin ice east",new Vector2(6,-2.1f),new Vector2(5,.5f),true,3);Platform("Citadel refuge",new Vector2(0,.1f),new Vector2(4.5f,.5f));Platform("Patrol bridge west",new Vector2(-6,2.6f),new Vector2(4,.45f),true,2);Platform("Citadel east",new Vector2(6,2.6f),new Vector2(4,.45f));}
  if(number==5){Platform("Crown gallery west",new Vector2(-6,-1.8f),new Vector2(4,.45f));Platform("Crown gallery east",new Vector2(6,-1.8f),new Vector2(4,.45f));Platform("Aurora crown west",new Vector2(-5,1.1f),new Vector2(3.5f,.45f));Platform("Aurora crown east",new Vector2(5,1.1f),new Vector2(3.5f,.45f));}
  foreach(float x in new[]{-11.7f,11.7f}){var wall=new GameObject("Ice boundary");wall.layer=8;wall.transform.position=new Vector2(x,1);wall.AddComponent<BoxCollider2D>().size=new Vector2(.5f,13);}
  var game=new GameObject("Ice encounter "+number).AddComponent<GameManager>();game.level=Definition(number);game.enemyPrefabs=prefabs;game.particle=spark;game.players=new PlayerHealth[2];for(int i=0;i<2;i++){var hero=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(Heroes+(i==0?"Coral":"Celeste")+".prefab"));hero.transform.position=new Vector2(i==0?-6:6,-3.7f);hero.name=i==0?"Mora":"Lima";game.players[i]=hero.GetComponent<PlayerHealth>();game.players[i].spawn=hero.transform.position;PrefabUtility.RecordPrefabInstancePropertyModifications(game.players[i]);PrefabUtility.RecordPrefabInstancePropertyModifications(hero.transform);}
  var beam=new GameObject("Cooperative link").AddComponent<CoopBeam.CoopBeam>();beam.red=game.players[0];beam.blue=game.players[1];beam.core=Line(beam.transform,"Core",.055f,7);beam.halo=Line(beam.transform,"Halo",.24f,6);beam.outline=Line(beam.transform,"Outline",.13f,5);beam.outline.startColor=beam.outline.endColor=new Color(.08f,.08f,.2f);var exit=game.gameObject.AddComponent<CandyLevelExit>();exit.game=game;var hud=new GameObject("Winter HUD").AddComponent<CandyPixelHUD>();hud.game=game;hud.exit=exit;new GameObject("Snowfall").AddComponent<IceAtmosphere>().level=number;EditorSceneManager.SaveScene(scene,CandyCampaign.ScenePath(number,true));
 }
 static LineRenderer Line(Transform parent,string name,float width,int order){var g=new GameObject(name);g.transform.SetParent(parent);var r=g.AddComponent<LineRenderer>();r.sharedMaterial=mat;r.positionCount=2;r.useWorldSpace=true;r.widthMultiplier=width;r.sortingOrder=order;return r;}
 static CandyLevelDefinition Definition(int n){var d=ScriptableObject.CreateInstance<CandyLevelDefinition>();d.number=n;d.iceKingdom=true;d.title=Titles[n-1];d.lesson=Lessons[n-1];d.boss=n==5;int[][] waves=n==1?new[]{new[]{0,5},new[]{0,2,5},new[]{0,0,2}}:n==2?new[]{new[]{2,0,2},new[]{2,3,0},new[]{1,2,0,2}}:n==3?new[]{new[]{3,5,0},new[]{3,4,5},new[]{1,3,4,5}}:n==4?new[]{new[]{1,2,4},new[]{3,4,1,5},new[]{1,4,2,3,0}}:new[]{new[]{0,2,5},new[]{1,3,4},new[]{6}};d.waves=new CandyWave[3];for(int w=0;w<3;w++){d.waves[w]=new CandyWave{enemyTypes=waves[w],spawnPositions=new Vector2[waves[w].Length]};for(int i=0;i<waves[w].Length;i++){int k=waves[w][i];float x=waves[w].Length==1?0:(i-(waves[w].Length-1)*.5f)*4;float y=k==3?2.6f:k==6?-2.65f:-3.65f;if(k==4&&n>=3){x=n==5?5:6;y=n==5?1.825f:3.6f;}d.waves[w].spawnPositions[i]=new Vector2(x,y);}}AssetDatabase.CreateAsset(d,Root+"0_7_LevelData/Ice_Level_0"+n+".asset");return d;}
}
